 <body>
   <div id="root"></div>

   <script>
     const notificationOptions = [
       { id: "email", label: "Email" },
       { id: "sms", label: "SMS" },
       { id: "push", label: "Push Notifications" }
     ];

     const NotificationOption = ({ id, label }) => `
       <label class="radio-option" for="${id}">
         <input type="radio" id="${id}" name="notificationPreference" value="${label}" required>
         <span class="radio-text">${label}</span>
       </label>
     `;

     const RadioQuestion = ({ question, options }) => `
       <div class="form-field">
         <p class="field-label">${question}</p>
         <div class="radio-group" role="radiogroup" aria-label="${question}">
           ${options.map(NotificationOption).join("")}
         </div>
       </div>
     `;

     const SubmitButton = ({ label }) => `
       <div class="actions">
         <button class="submit-button" type="submit">${label}</button>
       </div>
     `;

     const App = () => `
       <main class="page-shell">
         <section class="form-card">
           <p class="eyebrow">Preferences</p>
           <h1>Choose your notification method</h1>
           <p class="intro">Select how you would like to receive updates. Only one option can be chosen before submitting the form.</p>
           <form>
             ${RadioQuestion({
               question: "How do you prefer to receive notifications?",
               options: notificationOptions
             })}
             ${SubmitButton({ label: "Submit" })}
           </form>
         </section>
       </main>
     `;

     document.getElementById("root").innerHTML = App();
   </script>
 </body>
